// search_files tool implementation (abridged)
async function searchFiles(pattern, dir = '.') {
  const { stdout } = await execAsync('rg -n --no-heading -m 30 "' +
    pattern.replace(/"/g, '\\"') + '" ' + dir, { cwd: ROOT });
  const lines = stdout.split('\n').filter(Boolean);
  if (lines.length === 0) return 'No matches found. Try a broader term.';
  return lines.slice(0, 30).join('\n')
    + (lines.length > 30 ? '\n... (' + lines.length + ' total)' : '');
}

async function readFileRange(file, start, end) {
  const full = path.normalize(path.join(ROOT, file));
  if (!full.startsWith(ROOT)) return 'Error: path escapes project root.';
  const text = await readFile(full, 'utf8');
  const lines = text.split('\n');
  const from = Math.max(1, start || 1);
  const to = Math.min(lines.length, end || from + 80);
  return lines.slice(from - 1, to)
              .map((l, i) => (from + i) + ': ' + l).join('\n');
}

