function validatePlan(raw) {
  let plan;
  try { plan = JSON.parse(raw); } catch { return null; }
  if (!plan || typeof plan.goal !== 'string') return null;
  if (!Array.isArray(plan.steps) || plan.steps.length === 0) return null;
  if (plan.steps.length > 12) return null; // keep plans focused
  return plan;
}

