import { readdir, readFile } from 'node:fs/promises';
import * as path from 'node:path';

async function loadSkills(task) {
  const dir = path.join(ROOT, 'skills');
  const files = (await readdir(dir).catch(() => [])).filter(f => f.endsWith('.md'));
  const loaded = [];
  for (const f of files) {
    const doc = await readFile(path.join(dir, f), 'utf8');
    const desc = doc.match(/^description:\s*(.+)$/m)?.[1] || f;
    if (task.toLowerCase().includes(desc.toLowerCase().split(' ')[0])) {
      loaded.push('## Skill: ' + f + '\n' + doc);
    }
  }
  return loaded.join('\n\n');
}

